async function primaryRecord(f:Awaited<ReturnType<typeof fixture>>){const state=authenticatedOutcomeRequestState(f.request);const binding=await f.ledger.lookupIngress(state.requestKey);assert.ok(binding);const found=await f.sink.lookupPrimaryByIngress(binding.ingressClaimDigest);assert.equal(found.ok,true);if(!found.ok||found.status!=="found")throw new Error("primary decision missing");return found.record;}

function optionsForReason(reason:GateRefusalReason):FixtureOverrides{const reserve=["reservation-idempotency-conflict","semantic-duplicate","capability-integrity","capability-already-reserved","limit-exceeded","not-yet-valid","expired","clock-rollback","integrity-failure","busy","lock-owner-unverifiable","corruption"];if(reserve.includes(reason))return{reserveReason:reason==="reservation-idempotency-conflict"?"idempotency-conflict":reason};switch(reason){case"authority-state-invalid":return{snapshot:base=>({...base,stateVersion:0})};case"authority-state-rollback":return{advance:"rollback"};case"authority-state-changed":return{advance:"changed"};case"contract-not-found":return{snapshot:base=>({...base,candidates:[]})};case"contract-untrusted":return{snapshot:base=>({...base,candidates:[{...base.candidates[0],contractEnvelope:{...base.candidates[0].contractEnvelope,signerId:"untrusted"}}]})};case"contract-alias-mismatch":return{contract:{alias:"definition_2"}};case"contract-audience-mismatch":return{contract:{audiences:["other"]}};case"contract-inactive":return{snapshot:base=>({...base,candidates:[{...base.candidates[0],stateEvents:[]}]})};case"contract-revoked":return{snapshot:base=>({...base,candidates:[{...base.candidates[0],stateEvents:[...base.candidates[0].stateEvents,{index:1,kind:"revoked",contractDigest:base.candidates[0].stateEvents[0].contractDigest,at:"2026-01-04T00:00:00.000Z"}]}]})};case"contract-not-yet-valid":return{contract:{validFrom:"2026-01-16T00:00:00.000Z"}};case"contract-expired":return{contractValidUntil:planAt};case"delegation-invalid":return{grant:{grantee:"other_gate"}};case"pack-mismatch":return{contract:{packDigest:sha("e")}};case"definition-mismatch":return{contract:{definitionDigest:sha("e")}};case"resolver-mismatch":return{contract:{sourceAuthority:{resolverId:"resolver_missing",projectionSchemaId:"projection/v1",allowedReadEndpointIds:["read_1"],authorizedProjectionPointers:["/message"],maxFreshnessSeconds:60}}};case"connector-mismatch":return{contract:{connectorId:"connector_missing"},grant:{constraints:grantConstraints("connector_missing","account_1")}};case"account-mismatch":return{contract:{accountId:"account_missing"},grant:{constraints:grantConstraints("connector_1","account_missing")}};case"endpoint-not-allowed":return{pack:{writeEndpointIds:["write_2"]}};case"risk-not-allowed":return{pack:{riskClasses:["other"]}};case"source-read-refused":return{reads:"refused"};case"source-observation-invalid":return{observation:"malformed"};case"source-projection-invalid":return{sourceProject:"throw"};case"source-ungrounded":return{sourceProject:"ungrounded"};case"source-stale":return{clock:[planAt,"2026-01-15T00:02:00.000Z"]};case"choices-invalid":return{pack:{validateChoices:()=>{throw new TypeError("choices");}}};case"compile-refused":return{pack:{compile:()=>{throw new TypeError("compile");}}};case"effect-refused":return{effect:{method:"GET"}};case"contract-not-eligible":return{snapshot:base=>({...base,candidates:[{...base.candidates[0],stateEvents:[]},{...base.candidates[0],stateEvents:[{...base.candidates[0].stateEvents[0],at:"2027-01-01T00:00:00.000Z"}]}]})};case"contract-ambiguous":return{snapshot:base=>({...base,candidates:[base.candidates[0],{...base.candidates[0],stateEvents:[...base.candidates[0].stateEvents,{index:1,kind:"revoked",contractDigest:base.candidates[0].stateEvents[0].contractDigest,at:"2027-01-01T00:00:00.000Z"}]}]})};default:return{};}}

