test("gate ordering fixes both clock boundaries, fresh read-refusal time, Event-ID boundaries, and keeps network outside the lease",async()=>{const planning=await fixture({snapshot:base=>({...base,candidates:[]})});try{await planning.gate.decide(planning.request);assert.deepEqual(planning.trace.slice(0,5),["clock","load","advance","event-id","sign"]);}finally{await planning.cleanup();}const read=await fixture({reads:"refused",clock:[planAt,"2026-01-15T00:00:31.000Z"]});try{await read.gate.decide(read.request);assert.deepEqual(read.trace.filter(x=>["clock","load","advance","read","event-id","sign"].includes(x)),["clock","load","advance","read","clock","event-id","sign"]);assert.equal((await primaryRecord(read)).gateEvent.at,"2026-01-15T00:00:31.000Z");}finally{await read.cleanup();}const eventFailure=await fixture({eventIdMode:"invalid"});try{assert.deepEqual(await eventFailure.gate.decide(eventFailure.request),{kind:"unavailable",reason:"event-id-unavailable"});assert.equal(eventFailure.trace.includes("reserve"),false);}finally{await eventFailure.cleanup();}const accepted=await fixture();const originalFetch=globalThis.fetch;globalThis.fetch=(()=>{throw new Error("network inside gate");}) as typeof fetch;try{assert.equal((await accepted.gate.decide(accepted.request)).kind,"accepted");assert.ok(accepted.trace.indexOf("event-id")<accepted.trace.indexOf("reserve"));assert.ok(accepted.trace.indexOf("reserve")<accepted.trace.indexOf("sign"));}finally{globalThis.fetch=originalFetch;await accepted.cleanup();}});

