test("simultaneous trusted-candidate failures use union precedence instead of message or object order",async()=>{
  const inactive=(base:AuthorityStateSnapshot)=>({...base,candidates:[{...base.candidates[0],stateEvents:[]}]});
  const revoked=(base:AuthorityStateSnapshot)=>({...base,candidates:[{...base.candidates[0],stateEvents:[...base.candidates[0].stateEvents,{index:1,kind:"revoked" as const,contractDigest:base.candidates[0].stateEvents[0].contractDigest,at:"2026-01-04T00:00:00.000Z"}]}]});
  const cases:readonly [FixtureOverrides,GateRefusalReason][]=[
    [{contract:{audiences:["other"],alias:"definition_2"}},"contract-alias-mismatch"],
    [{contract:{audiences:["other"]},snapshot:inactive},"contract-audience-mismatch"],
    [{snapshot:revoked,contract:{validFrom:"2026-01-16T00:00:00.000Z"}},"contract-revoked"],
    [{grant:{grantee:"other_gate"},contract:{packDigest:sha("e")}},"delegation-invalid"],
    [{contract:{packDigest:sha("e"),definitionDigest:sha("f")}},"pack-mismatch"],
    [{contract:{definitionDigest:sha("e"),sourceAuthority:{resolverId:"resolver_missing",projectionSchemaId:"projection/v1",allowedReadEndpointIds:["read_1"],authorizedProjectionPointers:["/message"],maxFreshnessSeconds:60}}},"definition-mismatch"],
    [{contract:{sourceAuthority:{resolverId:"resolver_missing",projectionSchemaId:"projection/v1",allowedReadEndpointIds:["read_1"],authorizedProjectionPointers:["/message"],maxFreshnessSeconds:60}},pack:{writeEndpointIds:["write_2"]}},"resolver-mismatch"],
    [{pack:{writeEndpointIds:["write_2"],riskClasses:["other"]}},"endpoint-not-allowed"],
  ];
  for(const [overrides,want] of cases){const f=await fixture(overrides);try{const result=await f.gate.decide(f.request);assert.equal(result.kind,"refused");if(result.kind==="refused")assert.equal(result.status.reasonCode,want);}finally{await f.cleanup();}}
});

