test("a unique signature-trusted but ineligible candidate stages its contract digest in a multi-candidate refusal",async()=>{
  let trustedDigest="",untrustedDigest="";
  const f=await fixture({snapshot:base=>{
    const trusted={...base.candidates[0],stateEvents:[]};trustedDigest=trusted.contractEnvelope.advertisedDigest;
    const stored=JSON.parse(Buffer.from(base.candidates[0].contractEnvelope.canonicalBase64,"base64").toString("utf8")) as Record<string,unknown>,untrustedContract={...stored,contractId:"contract_untrusted"};untrustedDigest=authorityDigest(untrustedContract);
    const untrusted={...base.candidates[0],contractEnvelope:{canonicalBase64:authorityCanonicalBytes(untrustedContract).toString("base64"),advertisedDigest:untrustedDigest,signerId:"unknown",signature:signAuthorityDigest(gatePrivate,"outcome-contract",untrustedDigest)},stateEvents:[]};
    return{...base,candidates:[untrusted as never,trusted]};
  }});
  try{
    assert.notEqual(untrustedDigest,trustedDigest);
    const result=await f.gate.decide(f.request);
    assert.equal(result.kind,"refused");
    if(result.kind==="refused")assert.equal(result.status.reasonCode,"contract-not-eligible");
    const record=await primaryRecord(f);
    assert.equal(record.decisionContext.contractDigest,trustedDigest);
    assert.notEqual(record.decisionContext.contractDigest,untrustedDigest);
  }finally{await f.cleanup();}
});

test("one hundred exact requests create exactly one reservation, primary decision, capability, signature, and handle",async()=>{const f=await fixture();try{const results=await Promise.all(Array.from({length:100},()=>f.gate.decide(f.request)));assert.equal(results.filter((x:GateResult)=>x.kind==="accepted").length,1);assert.equal(results.filter((x:GateResult)=>x.kind==="existing"||(x.kind==="unavailable"&&x.reason==="decision-missing")).length,99);assert.equal(results.filter((x:GateResult)=>"handle" in x).length,1);const recovered=await f.ledger.recover();assert.equal(recovered.ok,true);if(recovered.ok)assert.equal(recovered.reservations.length,1);const binding=await f.ledger.lookupIngress(authenticatedOutcomeRequestState(f.request).requestKey);assert.ok(binding);const primary=await f.sink.lookupPrimaryByIngress(binding.ingressClaimDigest);assert.equal(primary.ok,true);if(primary.ok)assert.equal(primary.status,"found");assert.equal(f.counts().capabilities,1);assert.equal(f.counts().signatures,1);assert.equal(f.counts().loads,1);assert.equal(f.counts().reads,1);}finally{await f.cleanup();}});

