test("redacted results have exact keys, and accepted existing status follows the live ledger lifecycle",async()=>{
  const statusKeys=["decisionContextDigest","gateEventDigest","lifecycleState","reasonCode","requestId","requestKey","updatedAt","verdict"];
  const refused=await fixture({snapshot:base=>({...base,candidates:[]})});
  try{
    const first=await refused.gate.decide(refused.request);assert.equal(first.kind,"refused");
    if(first.kind==="refused"){assert.deepEqual(Object.keys(first.status).sort(),statusKeys);assert.equal(first.status.lifecycleState,"refused");assert.equal(first.status.updatedAt,planAt);assert.equal("receiptRef" in first.status,false);}
    const retry=await refused.gate.decide(refused.request);assert.equal(retry.kind,"existing");
    if(retry.kind==="existing")assert.deepEqual(Object.keys(retry.status).sort(),statusKeys);
  }finally{await refused.cleanup();}

  const later="2026-01-15T00:00:45.000Z",accepted=await fixture({clock:[planAt,decisionAt,decisionAt,later]});
  try{
    const first=await accepted.gate.decide(accepted.request);assert.equal(first.kind,"accepted");if(first.kind!=="accepted")return;
    assert.equal((await accepted.ledger.transition(first.signedDecision.reservationId!,"reserved",{to:"dispatched"})).ok,true);
    const retry=await accepted.gate.decide(accepted.request);assert.equal(retry.kind,"existing");
    if(retry.kind==="existing"){
      assert.deepEqual(Object.keys(retry.status).sort(),statusKeys);
      assert.equal(retry.status.lifecycleState,"dispatched");
      assert.equal(retry.status.updatedAt,later);
      assert.equal("receiptRef" in retry.status,false);
      for(const privateKey of ["eventId","capabilityId","decisionContext","signedDecision","handle","signerId","signature"])assert.equal(privateKey in retry.status,false,privateKey);
    }
  }finally{await accepted.cleanup();}
});

