test("the complete sink handling matrix covers valid collisions and all appended lookup outcomes",async()=>{
  const primaryCollision=await fixture({sinkAppend:"primary-ingress-conflict-found"});try{const result=await primaryCollision.gate.decide(primaryCollision.request);assert.equal(result.kind,"existing");assert.equal("handle" in result,false);assert.deepEqual(primaryCollision.sinkCalls.map(call=>call.operation),["append","primary"]);}finally{await primaryCollision.cleanup();}
  const reservationCollision=await fixture({sinkAppend:"reservation-conflict-found"});try{
    assert.deepEqual(await reservationCollision.gate.decide(reservationCollision.request),{kind:"unavailable",reason:"internal-integrity-unavailable"});assert.deepEqual(reservationCollision.sinkCalls.map(call=>call.operation),["append","reservation"]);
    const found=reservationCollision.seededReservationCollision();assert.notEqual(authorityCanonicalBytes(found).toString("utf8"),reservationCollision.attemptedAppendCanonical());assert.equal(found.gateEvent.eventId,"event_collision");assert.equal(verifyAuthoritySignature(createPublicKey(gatePrivate),"gate-event",found.gateEventDigest,found.signature),true);
    const linkage=await (reservationCollision.ledger as unknown as {lookupReservationLinkage(id:string):Promise<{ingressClaimDigest:string;capabilityDigest:string;decisionContextDigest:string}|undefined>}).lookupReservationLinkage(found.reservationId);assert.ok(linkage);assert.equal(linkage.ingressClaimDigest,found.ingressClaimDigest);assert.equal(linkage.capabilityDigest,found.decisionContext.capabilityDigest);assert.equal(linkage.decisionContextDigest,found.decisionContextDigest);
  }finally{await reservationCollision.cleanup();}

  for(const [sinkLookup,reason] of [["absent","internal-integrity-unavailable"],["corruption","internal-integrity-unavailable"],["unavailable","sink-unavailable"],["throw","sink-unavailable"]] as const){
    const f=await fixture({sinkLookup});try{assert.deepEqual(await f.gate.decide(f.request),{kind:"unavailable",reason});assert.deepEqual(f.sinkCalls.map(call=>call.operation),["append","event"]);}finally{await f.cleanup();}
  }

  for(const sinkAppend of [undefined,"idempotent"] as const){
    const refused=await fixture({sinkAppend,snapshot:base=>({...base,candidates:[]})});
    try{const result=await refused.gate.decide(refused.request);assert.equal(result.kind,sinkAppend?"existing":"refused");assert.deepEqual(refused.sinkCalls.map(call=>call.operation),["append","event","primary"]);}finally{await refused.cleanup();}
    const conflict=await fixture({sinkAppend});
    try{
      assert.equal((await conflict.ledger.bindIngress(authenticateOutcomeRequest({tenant:"tenant_1",requester:"requester_1",definitionAlias:"definition_1",request:{v:"reelier.outcome-request/v1",requestId:"request_1",sourceRefs:{item:"other"},choices:{}}}))).ok,true);
      const result=await conflict.gate.decide(conflict.request);assert.equal(result.kind,"refused");assert.deepEqual(conflict.sinkCalls.map(call=>call.operation),["append","event"]);
    }finally{await conflict.cleanup();}
  }
});

test("sink idempotent rereads every accepted index and returns existing without reconstructing a handle",async()=>{const f=await fixture({sinkAppend:"idempotent"});try{const result=await f.gate.decide(f.request);assert.equal(result.kind,"existing");assert.equal("handle" in result,false);assert.deepEqual(f.sinkCalls.map(call=>call.operation),["append","event","primary","reservation"]);}finally{await f.cleanup();}});

test("every found-record trust edge is reverified on appended, idempotent, and exact-existing reads",async()=>{
  for(const mutation of ["signature","signer","tenant","context-digest","event-digest","ingress-link","reservation-link"] as const){
    for(const sinkAppend of [undefined,"idempotent"] as const){
      const f=await fixture({sinkAppend,sinkFoundMutation:mutation});
      try{
        assert.deepEqual(await f.gate.decide(f.request),{kind:"unavailable",reason:"internal-integrity-unavailable"},`${sinkAppend??"appended"}:${mutation}`);
      }finally{await f.cleanup();}
    }
    const existing=await fixture();
    try{
      assert.equal((await existing.gate.decide(existing.request)).kind,"accepted");
      existing.setSinkFoundMutation(mutation);
      assert.deepEqual(await existing.gate.decide(existing.request),{kind:"unavailable",reason:"internal-integrity-unavailable"},`existing:${mutation}`);
    }finally{await existing.cleanup();}
  }
});

test("a conflict record must differ from its verified owner in alias or request digest",async()=>{
  const f=await fixture({sinkFoundMutation:"conflict-no-difference"});
  try{
    const owner=authenticateOutcomeRequest({tenant:"tenant_1",requester:"requester_1",definitionAlias:"definition_2",request:{v:"reelier.outcome-request/v1",requestId:"request_1",sourceRefs:{item:"opaque_1"},choices:{}}});
    assert.equal((await f.ledger.bindIngress(owner)).ok,true);
    assert.deepEqual(await f.gate.decide(f.request),{kind:"unavailable",reason:"internal-integrity-unavailable"});
  }finally{await f.cleanup();}
});

test("reserved dispatch handle freezes private state, serializes empty, and rejects clone/structural/symbol forgeries",()=>{const mutable={reservationId:"reservation_1",nested:{capabilityId:"capability_1"}};const handle=createReservedDispatchHandle(mutable);mutable.reservationId="attacker";mutable.nested.capabilityId="attacker";assert.equal(Object.isFrozen(handle),true);assert.deepEqual(Object.keys(handle),[]);assert.equal(JSON.stringify(handle),"{}");assert.deepEqual(unwrapReservedDispatchHandle(handle),{reservationId:"reservation_1",nested:{capabilityId:"capability_1"}});assert.throws(()=>unwrapReservedDispatchHandle({} as never),/reserved dispatch handle/i);assert.throws(()=>unwrapReservedDispatchHandle(structuredClone(handle) as never),/reserved dispatch handle/i);for(const symbol of Object.getOwnPropertySymbols(handle))assert.throws(()=>unwrapReservedDispatchHandle({[symbol]:true} as never),/reserved dispatch handle/i);});
